    mm = 0x00
    ss = 0x00
    pm = 0
    cur_reset = 0
    cur_ena = 0
    result = []

    def bcd_inc(v):
        lo = v & 0x0F
        hi = (v >> 4) & 0x0F
        lo += 1
        if lo == 10:
            lo = 0
            hi += 1
            if hi == 10:
                hi = 0
        return (hi << 4) | lo

